package com.coraline.postgame;

import java.nio.file.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.LevelResource;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.event.level.BlockEvent;
import net.minecraftforge.eventbus.api.*;
import net.minecraftforge.fml.common.Mod;

/** One native final encounter and roll-forward complete-ending transaction.
 * No debug completion flags, inventory copies, world-folder deletion or timer
 * victories. Only a killed manifestation exposes the physically broken core. */
@Mod.EventBusSubscriber(modid="coraline")
public final class TrueHeartBattle extends SavedData {
    private static final String NAME="coraline_true_heart";
    private enum Stage { IDLE, BUILDING, READY, ANCHORS, BODY, CORE, RESETTING, DONE, FAILED }
    private enum Step { RETURN, INFECTION, OWNERS, TYCOON, BREACH, EPOCH }
    private CompoundTag raw;private String problem="";
    private record Consent(UUID token,long expires){}
    private record BreakIntent(UUID owner,long tick){}
    private static final Map<MinecraftServer,Map<UUID,Consent>> CONSENTS=new WeakHashMap<>();
    private static final Map<MinecraftServer,BreakIntent> BREAKS=new WeakHashMap<>();
    private static final Map<MinecraftServer,java.util.concurrent.CompletableFuture<?>> LOADS=new WeakHashMap<>();
    private static final BlockPos CORE=new BlockPos(0,81,0),ENTRY=new BlockPos(0,81,-6);
    private static final List<BlockPos> PARTS=List.of(CORE,new BlockPos(-24,81,0),new BlockPos(24,81,0),new BlockPos(0,81,24),new BlockPos(0,81,-24));
    private TrueHeartBattle(){raw=new CompoundTag();raw.putInt("Version",1);raw.putString("Stage",Stage.IDLE.name());raw.put("PendingPlayers",new CompoundTag());}
    private TrueHeartBattle(CompoundTag n){raw=n.copy();try{if(!n.contains("Version",Tag.TAG_INT)||n.getInt("Version")!=1||!n.contains("Stage",Tag.TAG_STRING)||!n.contains("PendingPlayers",Tag.TAG_COMPOUND)||n.getCompound("PendingPlayers").size()>4096)throw new IllegalArgumentException("Invalid final encounter journal");for(String owner:n.getCompound("PendingPlayers").getAllKeys())if(!UUID.fromString(owner).toString().equals(owner)||!n.getCompound("PendingPlayers").hasUUID(owner))throw new IllegalArgumentException("Invalid pending player cleanup");var stage=Stage.valueOf(n.getString("Stage"));if(stage!=Stage.IDLE){for(String key:List.of("Generation","Reset","Owner"))if(!n.hasUUID(key))throw new IllegalArgumentException("Missing final encounter identity");for(String key:List.of("Built","Anchors","Navigation","Timing","Survival"))if(!n.contains(key,Tag.TAG_INT)||n.getInt(key)<0)throw new IllegalArgumentException("Invalid mechanism state");if(n.getInt("Built")>layout().size()||n.getInt("Anchors")>7||n.getInt("Navigation")>3||n.getInt("Timing")>3||n.getInt("Survival")>400)throw new IllegalArgumentException("Unbounded final encounter");if(stage==Stage.ANCHORS||stage==Stage.BODY||stage==Stage.CORE||stage==Stage.RESETTING||stage==Stage.DONE)if(!n.hasUUID("Body")||!n.hasUUID("Seal"))throw new IllegalArgumentException("Missing manifestation admission");if(stage==Stage.CORE||stage==Stage.RESETTING||stage==Stage.DONE)if(!n.hasUUID("Victory")||!n.hasUUID("KilledBy")||!n.contains("KilledAt",Tag.TAG_LONG)||n.getLong("KilledAt")<0)throw new IllegalArgumentException("Missing physical victory");if(stage==Stage.RESETTING||stage==Stage.DONE){if(!n.hasUUID("CoreBrokenBy")||!n.contains("Scope",Tag.TAG_LIST)||!n.contains("Cursor",Tag.TAG_INT)||!n.contains("Step",Tag.TAG_STRING))throw new IllegalArgumentException("Missing ending commitment");Step.valueOf(n.getString("Step"));var scope=n.getList("Scope",Tag.TAG_INT_ARRAY);if(scope.isEmpty()||scope.size()>4096||scope.size()!=((ListTag)n.get("Scope")).size()||n.getInt("Cursor")<0||n.getInt("Cursor")>scope.size())throw new IllegalArgumentException("Invalid ending scope");var ids=new HashSet<UUID>();for(var tag:scope)if(!(tag instanceof IntArrayTag array)||array.getAsIntArray().length!=4||!ids.add(NbtUtils.loadUUID(tag)))throw new IllegalArgumentException("Duplicate ending owner");}}}catch(IllegalArgumentException bad){problem=bad.getMessage();}}
    private static Path file(MinecraftServer server){return server.getWorldPath(LevelResource.ROOT).resolve("data/"+NAME+".dat");}
    private static TrueHeartBattle get(MinecraftServer server){return server.overworld().getDataStorage().computeIfAbsent(TrueHeartBattle::new,()->Files.notExists(file(server),LinkOption.NOFOLLOW_LINKS)?new TrueHeartBattle():new TrueHeartBattle(new CompoundTag()),NAME);}
    private Stage stage(){return Stage.valueOf(raw.getString("Stage"));}
    private boolean commit(MinecraftServer server){if(!problem.isEmpty())return false;try{if(Files.isSymbolicLink(file(server))||Files.isSymbolicLink(file(server).getParent()))throw new java.io.IOException("Ambiguous final encounter storage");setDirty();server.overworld().getDataStorage().save();if(!com.coraline.rebirth.StoryRunStore.read(file(server)).getCompound("data").equals(raw))throw new java.io.IOException("Final encounter save did not match");return true;}catch(java.io.IOException|RuntimeException bad){problem="The final encounter checkpoint could not be confirmed";return false;}}
    @Override public CompoundTag save(CompoundTag n){return n.merge(raw.copy());}
    public static Optional<UUID> pendingReset(MinecraftServer server,UUID owner){var d=get(server);return d.problem.isEmpty()&&d.raw.getCompound("PendingPlayers").hasUUID(owner.toString())?Optional.of(d.raw.getCompound("PendingPlayers").getUUID(owner.toString())):Optional.empty();}
    public static boolean encounterActive(MinecraftServer server){var d=get(server);return !d.problem.isEmpty()||d.stage()!=Stage.IDLE&&d.stage()!=Stage.DONE&&d.stage()!=Stage.FAILED;}
    public static boolean resetting(MinecraftServer server){var d=get(server);return !d.problem.isEmpty()||d.stage()==Stage.RESETTING;}
    public static boolean recoveryPending(ServerPlayer player){return resetting(player.server)||pendingReset(player.server,player.getUUID()).isPresent();}
    private boolean realm(ServerLevel level){return problem.isEmpty()&&raw.hasUUID("Generation")&&level.dimension().equals(TrueHeartRealm.key(raw.getUUID("Generation")))&&InfiniteWorldData.get(level.getServer()).matchesGeneration(raw.getUUID("Generation"));}
    static boolean owns(TrueHeartEntity body){if(!(body.level() instanceof ServerLevel level)||body.seal()==null)return false;var d=get(level.getServer());return d.realm(level)&&d.raw.hasUUID("Body")&&d.raw.getUUID("Body").equals(body.getUUID())&&d.raw.getUUID("Seal").equals(body.seal())&&(d.stage()==Stage.ANCHORS||d.stage()==Stage.BODY||d.stage()==Stage.CORE);}
    static boolean fighting(TrueHeartEntity body){if(!owns(body))return false;var d=get(body.getServer());var owner=body.getServer().getPlayerList().getPlayer(d.raw.getUUID("Owner"));return d.stage()==Stage.BODY&&owner!=null&&owner.isAlive()&&!owner.isCreative()&&!owner.isSpectator()&&owner.level()==body.level();}
    static void defeated(TrueHeartEntity body,net.minecraft.world.damagesource.DamageSource source){if(!owns(body))return;var d=get(body.getServer());if(d.stage()!=Stage.BODY)return;if(body.getHealth()>0||!(source.getEntity() instanceof ServerPlayer p)||!p.isAlive()||p.isCreative()||p.isSpectator()||p.level()!=body.level()){d.raw.putString("Stage",Stage.FAILED.name());d.commit(body.getServer());return;}d.raw.putUUID("Victory",UUID.randomUUID());d.raw.putUUID("KilledBy",p.getUUID());d.raw.putLong("KilledAt",body.level().getGameTime());d.raw.putString("Stage",Stage.CORE.name());if(d.commit(body.getServer())){d.sync((ServerLevel)body.level());tell(p,"heart_core_exposed");}}
    private static void tell(ServerPlayer p,String key,Object... args){p.sendSystemMessage(Component.translatable("message.coraline."+key,args));}
    private static final Map<MinecraftServer,String> SCOPE_PROBLEMS=new WeakHashMap<>();
    private static Set<UUID> scope(MinecraftServer server){
        var owners=new TreeSet<UUID>();SCOPE_PROBLEMS.remove(server);
        owners.addAll(com.coraline.tycoon.TycoonData.get(server).homes.keySet());
        owners.addAll(com.coraline.feast.VisitData.get(server).scenes.keySet());
        for(var family:com.coraline.parents.FamilyData.get(server).families.values())if(family.owner!=null)owners.add(family.owner);
        owners.addAll(InfiniteWorldData.get(server).completionOwners());
        server.getPlayerList().getPlayers().forEach(p->owners.add(p.getUUID()));
        // Global reset includes offline players who have never owned a story or
        // Tycoon. Only UUID filenames are read; no ordinary player data is deleted.
        var directory=server.getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR);
        try{
            if(java.nio.file.Files.isSymbolicLink(directory))throw new java.io.IOException("Ambiguous player directory");
            if(!java.nio.file.Files.notExists(directory,java.nio.file.LinkOption.NOFOLLOW_LINKS))try(var entries=java.nio.file.Files.newDirectoryStream(directory,"*.dat")){
                for(var file:entries){String name=file.getFileName().toString();UUID id;
                    try{id=UUID.fromString(name.substring(0,name.length()-4));}catch(IllegalArgumentException unrelated){continue;}
                    if(!name.equals(id+".dat"))continue;
                    if(java.nio.file.Files.isSymbolicLink(file)||!java.nio.file.Files.isRegularFile(file,java.nio.file.LinkOption.NOFOLLOW_LINKS))throw new java.io.IOException("Ambiguous offline player save");
                    owners.add(id);if(owners.size()>4096)break;
                }
            }
        }catch(java.io.IOException|SecurityException failure){SCOPE_PROBLEMS.put(server,"The offline player scope could not be read safely");}
        return owners;
    }
    private static boolean eligible(ServerPlayer p){return !resetting(p.server)&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.level()==p.server.overworld()&&PostgameQuests.finalKnowledge(p)&&WybieRescue.nearReturnedWybie(p);}
    static void offer(ServerPlayer p){p.sendSystemMessage(Component.translatable("message.coraline.heart_prepare").withStyle(s->s.withClickEvent(new ClickEvent(ClickEvent.Action.RUN_COMMAND,"/coraline final_ending"))));}
    public static int leave(ServerPlayer p){return TrueHeartRealm.isHeart(p.level())&&TrueHeartRealm.leave(p)?1:0;}
    private static boolean capacity(MinecraftServer server,Set<UUID> owners){return !SCOPE_PROBLEMS.containsKey(server)&&com.coraline.tycoon.TycoonReceiptRecovery.readyForGlobalReset(server)&&com.coraline.tycoon.TycoonRetiredParcels.get(server).canCapture(com.coraline.tycoon.TycoonData.get(server).homes.values())&&InfiniteWorldData.get(server).state().canRetire()&&com.coraline.tycoon.TycoonData.get(server).canRetireHomes(owners)&&InfectionColonies.canRetire(server);}
    public static int request(ServerPlayer p){if(!eligible(p))return 0;var owners=scope(p.server);owners.add(p.getUUID());if(owners.size()>4096||!p.server.isSingleplayerOwner(p.getGameProfile())&&!p.hasPermissions(2)){tell(p,"heart_global_permission");return 0;}if(!capacity(p.server,owners)){tell(p,"heart_scope_capacity");return 0;}var token=UUID.randomUUID();CONSENTS.computeIfAbsent(p.server,s->new HashMap<>()).put(p.getUUID(),new Consent(token,p.server.overworld().getGameTime()+1200));tell(p,"heart_final_warning",owners.size());p.sendSystemMessage(Component.translatable("message.coraline.heart_confirm").withStyle(s->s.withClickEvent(new ClickEvent(ClickEvent.Action.RUN_COMMAND,"/coraline final_ending confirm "+token))));return 1;}
    public static int confirm(ServerPlayer p,UUID token){if(!eligible(p))return 0;var consent=CONSENTS.computeIfAbsent(p.server,s->new HashMap<>()).remove(p.getUUID());if(consent==null||!consent.token.equals(token)||p.server.overworld().getGameTime()>consent.expires)return 0;var owners=scope(p.server);owners.add(p.getUUID());if(owners.size()>4096||!p.server.isSingleplayerOwner(p.getGameProfile())&&!p.hasPermissions(2))return 0;if(!capacity(p.server,owners)){tell(p,"heart_scope_capacity");return 0;}var d=get(p.server);if(!d.problem.isEmpty())return 0;try{for(var owner:owners){var run=com.coraline.rebirth.StoryRunStore.get(p.server,owner);if(run.phase()!=com.coraline.rebirth.StoryRun.Phase.IDLE||run.rewardPending()){tell(p,"heart_finish_rituals");return 0;}}}catch(java.io.IOException ambiguous){tell(p,"quest_save_paused");return 0;}var generation=InfiniteWorldData.get(p.server).generation().orElse(null);if(generation==null)return 0;
        if(d.stage()!=Stage.IDLE&&d.stage()!=Stage.DONE&&d.stage()!=Stage.FAILED){if(d.raw.getUUID("Owner").equals(p.getUUID())&&d.raw.getUUID("Generation").equals(generation)){d.enter(p);return 1;}tell(p,"heart_in_use");return 0;}
        var pending=d.raw.getCompound("PendingPlayers").copy();var pendingOwners=new HashSet<UUID>(owners);for(String old:pending.getAllKeys())pendingOwners.add(UUID.fromString(old));if(pendingOwners.size()>4096){tell(p,"heart_scope_capacity");return 0;}d.raw=new CompoundTag();d.raw.putInt("Version",1);d.raw.put("PendingPlayers",pending);d.raw.putString("Stage",Stage.BUILDING.name());d.raw.putUUID("Generation",generation);d.raw.putUUID("Reset",UUID.randomUUID());d.raw.putUUID("Owner",p.getUUID());for(String key:List.of("Built","Anchors","Navigation","Timing","Survival"))d.raw.putInt(key,0);if(!d.commit(p.server))return 0;p.server.getPlayerList().broadcastSystemMessage(Component.translatable("message.coraline.heart_world_warning",p.getDisplayName()),false);return 1;}
    private static Map<BlockPos,BlockState> layout(){var out=new LinkedHashMap<BlockPos,BlockState>();for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)if(x*x+z*z<=72)out.put(new BlockPos(x,80,z),Blocks.SMOOTH_QUARTZ.defaultBlockState());for(int direction=0;direction<4;direction++)for(int step=8;step<=24;step++)for(int width=-1;width<=1;width++){int x=direction<2?(direction==0?-step:step):width,z=direction<2?width:(direction==2?step:-step);out.put(new BlockPos(x,80,z),InfiniteContent.block("mirrorstone").defaultBlockState());}for(int part=1;part<PARTS.size();part++){var at=PARTS.get(part);for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)out.put(at.offset(x,-1,z),InfiniteContent.block(part==3?"pale_rift_stone":"porcelain_stone").defaultBlockState());for(int y=-5;y<=-2;y++)out.put(at.offset(0,y,0),Blocks.QUARTZ_PILLAR.defaultBlockState());}for(int x:new int[]{8,14,20})out.put(new BlockPos(x,80,0),Blocks.CYAN_TERRACOTTA.defaultBlockState());for(int part=0;part<PARTS.size();part++)out.put(PARTS.get(part),com.coraline.registry.ModBlocks.TRUE_HEART_ANCHOR.get().defaultBlockState().setValue(TrueHeartAnchorBlock.PART,part));return out;}
    private void build(ServerLevel level){var cells=new ArrayList<>(layout().entrySet());int index=raw.getInt("Built"),limit=Math.min(cells.size(),index+128);for(;index<limit;index++){var cell=cells.get(index);if(!level.hasChunkAt(cell.getKey())){var pending=LOADS.get(level.getServer());if(pending==null||pending.isDone())LOADS.put(level.getServer(),level.getChunkSource().getChunkFuture(cell.getKey().getX()>>4,cell.getKey().getZ()>>4,net.minecraft.world.level.chunk.ChunkStatus.FULL,true));break;}var current=level.getBlockState(cell.getKey());if(!current.equals(cell.getValue())){if(!current.isAir()&&!(current.is(com.coraline.registry.ModBlocks.TRUE_HEART_ANCHOR.get())&&current.getValue(TrueHeartAnchorBlock.PART).equals(cell.getValue().hasProperty(TrueHeartAnchorBlock.PART)?cell.getValue().getValue(TrueHeartAnchorBlock.PART):-1))){raw.putString("Stage",Stage.FAILED.name());commit(level.getServer());return;}level.setBlock(cell.getKey(),cell.getValue(),3);}}raw.putInt("Built",index);setDirty();if(index==cells.size()){raw.putString("Stage",Stage.READY.name());commit(level.getServer());}}
    private void enter(ServerPlayer p){if(!eligible(p)||!raw.getUUID("Owner").equals(p.getUUID()))return;var level=TrueHeartRealm.ensure(p.server,raw.getUUID("Generation"));if(level==null||stage()==Stage.BUILDING||stage()==Stage.RESETTING||!level.hasChunkAt(ENTRY)||!com.coraline.tycoon.TycoonWorld.safeFeet(level,ENTRY))return;
        if(stage()==Stage.READY){var body=com.coraline.registry.ModEntities.TRUE_HEART.get().create(level);if(body==null)return;var seal=UUID.randomUUID();body.configure(seal);body.moveTo(0,82,2,180,0);body.setNoAi(true);if(!level.noCollision(body,body.getBoundingBox())){tell(p,"heart_clear_space");return;}raw.putUUID("Body",body.getUUID());raw.putUUID("Seal",seal);raw.putString("Stage",Stage.ANCHORS.name());if(!commit(p.server))return;if(!level.addFreshEntity(body)){raw.putString("Stage",Stage.FAILED.name());commit(p.server);return;}}
        if(stage()!=Stage.ANCHORS&&stage()!=Stage.BODY&&stage()!=Stage.CORE)return;p.stopRiding();p.stopUsingItem();p.setCamera(p);p.closeContainer();p.teleportTo(level,.5,81,-5.5,0,0);p.fallDistance=0;tell(p,"heart_entered");}
    private void sync(ServerLevel level){for(int part=0;part<PARTS.size();part++){var at=PARTS.get(part);if(!level.hasChunkAt(at))continue;var state=level.getBlockState(at);if(!state.is(com.coraline.registry.ModBlocks.TRUE_HEART_ANCHOR.get())||state.getValue(TrueHeartAnchorBlock.PART)!=part)continue;boolean sealed=part==0?stage()!=Stage.CORE:part<4&&(raw.getInt("Anchors")&(1<<(part-1)))==0;if(part==1&&sealed&&stage()==Stage.ANCHORS){int beat=(int)Math.floorMod(level.getGameTime(),80);sealed=beat<20||beat>30;}var next=state.setValue(TrueHeartAnchorBlock.SEALED,sealed);if(!state.equals(next))level.setBlock(at,next,3);}}
    static void interact(ServerPlayer p,BlockPos at){var d=get(p.server);if(!d.realm(p.serverLevel())||!p.isAlive()||p.isCreative()||p.isSpectator()||p.distanceToSqr(at.getCenter())>25||!d.raw.getUUID("Owner").equals(p.getUUID())||!p.level().mayInteract(p,at))return;int part=PARTS.indexOf(at);if(part==4){TrueHeartRealm.leave(p);return;}if(d.stage()!=Stage.ANCHORS||part<1||part>3)return;if((d.raw.getInt("Anchors")&(1<<(part-1)))!=0)return;
        if(part==1){long now=p.level().getGameTime();if(now-d.raw.getLong("LastTap")<8)return;d.raw.putLong("LastTap",now);int beat=(int)Math.floorMod(now,80);int count=beat>=20&&beat<=30?d.raw.getInt("Timing")+1:0;d.raw.putInt("Timing",count);tell(p,"heart_timing",count);if(count>=3)d.activate(p,part);else d.setDirty();}
        if(part==2){if(d.raw.getInt("Navigation")>=3)d.activate(p,part);else tell(p,"heart_navigation",d.raw.getInt("Navigation"));}
        if(part==3){d.raw.putBoolean("SurvivalStarted",true);d.setDirty();tell(p,"heart_survival");}}
    private void activate(ServerPlayer p,int part){raw.putInt("Anchors",raw.getInt("Anchors")|(1<<(part-1)));if(raw.getInt("Anchors")==7)raw.putString("Stage",Stage.BODY.name());if(commit(p.server)){sync(p.serverLevel());tell(p,raw.getInt("Anchors")==7?"heart_manifested":"heart_anchor_disabled");}}
    private void mechanisms(ServerPlayer owner){if(stage()!=Stage.ANCHORS)return;if((raw.getInt("Anchors")&2)==0){int step=raw.getInt("Navigation");if(step<3&&owner.onGround()&&owner.distanceToSqr(new BlockPos(new int[]{8,14,20}[step],81,0).getCenter())<4){raw.putInt("Navigation",step+1);setDirty();tell(owner,"heart_navigation",step+1);}}
        if(raw.getBoolean("SurvivalStarted")&&(raw.getInt("Anchors")&4)==0){if(owner.distanceToSqr(PARTS.get(3).getCenter())>36){raw.putInt("Survival",0);raw.remove("Pulse");setDirty();return;}int survived=raw.getInt("Survival")+20;raw.putInt("Survival",Math.min(400,survived));long now=owner.level().getGameTime();if(survived%80==20){raw.putLong("Pulse",now+20);((ServerLevel)owner.level()).sendParticles(net.minecraft.core.particles.ParticleTypes.END_ROD,0,80.1,24,30,3,.1,3,0);tell(owner,"heart_jump");}if(raw.contains("Pulse",Tag.TAG_LONG)&&now>=raw.getLong("Pulse")){raw.remove("Pulse");if(owner.onGround())owner.hurt(owner.damageSources().magic(),4);}if(survived>=400&&owner.isAlive())activate(owner,3);else setDirty();}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void breaking(BlockEvent.BreakEvent event){if(event.isCanceled()||!(event.getPlayer() instanceof ServerPlayer p)||!event.getPos().equals(CORE)||!event.getState().is(com.coraline.registry.ModBlocks.TRUE_HEART_ANCHOR.get()))return;var d=get(p.server);if(!d.realm(p.serverLevel())||d.stage()!=Stage.CORE||!p.isAlive()||p.isCreative()||p.isSpectator()||!d.raw.getUUID("Owner").equals(p.getUUID())||!p.server.isSingleplayerOwner(p.getGameProfile())&&!p.hasPermissions(2)){event.setCanceled(true);return;}if(!capacity(p.server,scope(p.server))){event.setCanceled(true);tell(p,"heart_scope_capacity");return;}var combined=new HashSet<UUID>(scope(p.server));for(String old:d.raw.getCompound("PendingPlayers").getAllKeys())combined.add(UUID.fromString(old));if(combined.size()>4096){event.setCanceled(true);tell(p,"heart_scope_capacity");return;}try{for(var owner:scope(p.server)){var run=com.coraline.rebirth.StoryRunStore.get(p.server,owner);if(run.phase()!=com.coraline.rebirth.StoryRun.Phase.IDLE||run.rewardPending()){event.setCanceled(true);tell(p,"heart_finish_rituals");return;}}}catch(java.io.IOException ambiguous){event.setCanceled(true);return;}BREAKS.put(p.server,new BreakIntent(p.getUUID(),p.level().getGameTime()));}
    static void coreRemoved(ServerLevel level,BlockPos at){var d=get(level.getServer());var intent=BREAKS.remove(level.getServer());if(!at.equals(CORE)||!d.realm(level)||d.stage()!=Stage.CORE||intent==null||intent.tick!=level.getGameTime()||!intent.owner.equals(d.raw.getUUID("Owner")))return;var owners=scope(level.getServer());owners.add(intent.owner);if(owners.size()>4096)return;var scope=new ListTag();for(var owner:owners)scope.add(NbtUtils.createUUID(owner));d.raw.put("Scope",scope);d.raw.putUUID("CoreBrokenBy",intent.owner);d.raw.putString("Stage",Stage.RESETTING.name());d.raw.putString("Step",Step.RETURN.name());d.raw.putInt("Cursor",0);var pending=d.raw.getCompound("PendingPlayers");for(var owner:owners)pending.putUUID(owner.toString(),d.raw.getUUID("Reset"));d.commit(level.getServer());}
    public static boolean authorizes(MinecraftServer server,UUID generation,UUID reset){var d=get(server);return d.problem.isEmpty()&&d.stage()==Stage.RESETTING&&d.raw.getUUID("Generation").equals(generation)&&d.raw.getUUID("Reset").equals(reset)&&d.raw.hasUUID("Victory")&&d.raw.hasUUID("CoreBrokenBy");}
    private boolean missingBody(ServerLevel level,ServerPlayer owner){
        if(stage()!=Stage.ANCHORS&&stage()!=Stage.BODY)return false;if(level.getEntity(raw.getUUID("Body")) instanceof TrueHeartEntity){raw.remove("MissingTicks");return false;}
        // The body is physically bounded to this sixteen-chunk arena. Wait
        // until all native entity sections are loaded before declaring loss.
        for(int x=-2;x<=1;x++)for(int z=-2;z<=1;z++)if(!level.hasChunk(x,z)||!level.areEntitiesLoaded(net.minecraft.world.level.ChunkPos.asLong(x,z))){raw.remove("MissingTicks");return false;}
        int missing=raw.getInt("MissingTicks")+20;raw.putInt("MissingTicks",missing);setDirty();if(missing<100)return false;raw.putString("Stage",Stage.FAILED.name());if(commit(level.getServer()))tell(owner,"heart_body_missing");return true;
    }
    private void resetTick(MinecraftServer server){CompleteEndingTransaction.advance(server,raw,()->commit(server));}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent event){if(event.phase!=TickEvent.Phase.END)return;var server=event.getServer();var d=get(server);if(!d.problem.isEmpty())return;if(server.getTickCount()%20!=0){if(d.stage()==Stage.ANCHORS){var loaded=server.getLevel(TrueHeartRealm.key(d.raw.getUUID("Generation")));if(loaded!=null)d.sync(loaded);}return;}if(d.stage()==Stage.RESETTING){d.resetTick(server);return;}if(d.stage()==Stage.IDLE||d.stage()==Stage.DONE||d.stage()==Stage.FAILED)return;if(!InfiniteWorldData.get(server).matchesGeneration(d.raw.getUUID("Generation")))return;var level=TrueHeartRealm.ensure(server,d.raw.getUUID("Generation"));if(level==null)return;if(d.stage()==Stage.BUILDING){d.build(level);return;}var owner=server.getPlayerList().getPlayer(d.raw.getUUID("Owner"));if(owner==null||!owner.isAlive()||owner.isCreative()||owner.isSpectator()){if(d.raw.getInt("Survival")>0){d.raw.putInt("Survival",0);d.raw.remove("Pulse");d.setDirty();}return;}if(d.stage()==Stage.READY){d.enter(owner);return;}if(owner.level()!=level){if(d.raw.getInt("Survival")>0){d.raw.putInt("Survival",0);d.raw.remove("Pulse");d.setDirty();}return;}if(d.missingBody(level,owner))return;d.sync(level);d.mechanisms(owner);}
    @SubscribeEvent public static void player(TickEvent.PlayerTickEvent event){if(event.phase!=TickEvent.Phase.END||!(event.player instanceof ServerPlayer p))return;var d=get(p.server);if(p.tickCount%20==0&&d.raw.getCompound("PendingPlayers").hasUUID(p.getUUID().toString()))CompleteEndingTransaction.player(p,d.raw,()->d.commit(p.server));if(!TrueHeartRealm.isHeart(p.level()))return;if(!d.problem.isEmpty()||p.getY()<60||d.stage()==Stage.DONE||d.stage()==Stage.FAILED||!d.realm(p.serverLevel())){if(p.isAlive())TrueHeartRealm.leave(p);}}
    @SubscribeEvent public static void respawn(PlayerEvent.PlayerRespawnEvent event){if(event.getEntity() instanceof ServerPlayer p&&TrueHeartRealm.isHeart(p.level()))TrueHeartRealm.leave(p);}
    @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(event.getEntity() instanceof ServerPlayer p)CompleteEndingTransaction.player(p,get(p.server).raw,()->get(p.server).commit(p.server));}
    @SubscribeEvent public static void stopped(net.minecraftforge.event.server.ServerStoppedEvent event){CONSENTS.remove(event.getServer());BREAKS.remove(event.getServer());LOADS.remove(event.getServer());}
}
